exec("def size(expr):\n    return 1 + sum(size(x) for x in expr[1:]) if isinstance(expr, tuple) else 1\n\ndef simplify(expr):\n    def num(x):\n        return isinstance(x, (int, float, complex))\n    if not isinstance(expr, tuple):\n        return expr\n    op = expr[0]\n    a = simplify(expr[1])\n    if op == 'neg':\n        if num(a):\n            return -a\n        if isinstance(a, tuple) and a[0] == 'neg':\n            return a[1]\n        return ('neg', a)\n    b = simplify(expr[2])\n    if num(a) and num(b):\n        return a + b if op == 'add' else a * b\n    if num(a) and not num(b):\n        a, b = b, a\n    if op == 'add':\n        if b == 0:\n            return a\n        if isinstance(a, tuple) and a[0] == 'add' and num(a[2]):\n            if num(b):\n                return simplify(('add', a[1], a[2] + b))\n            return simplify(('add', ('add', a[1], b), a[2]))\n        if isinstance(b, tuple) and b[0] == 'add' and num(b[2]):\n            return simplify(('add', ('add', a, b[1]), b[2]))\n    elif op == 'mul':\n        if b == 0:\n            return 0\n        if b == 1:\n            return a\n        if num(b) and isinstance(a, tuple):\n            if a[0] == 'mul' and num(a[2]):\n                return simplify(('mul', a[1], a[2] * b))\n            if a[0] == 'add':\n                return simplify(('add', ('mul', a[1], b), ('mul', a[2], b)))\n    return (op, a, b)\n")